// Cross-implementation parity for the Epitrochoid Generator: the same design
// must produce the same chain, the same traced curve and the same channel
// tracks here as it does in desktop GlyphViz.
//
// The fixture is generated by tools/dump_epicycles.py, which runs the REAL
// desktop `glyphviz_core/epicycles.py` — its ladder, its CPython `Fraction`
// closure search, its `build_nodes`, and its `trace_path`, which reads a live
// `Scene`. So what this diffs is the whole chain at once: the design model, the
// telescoped scales, the tube ratio, the tilt, the %g-formatted labels, the
// grouped alpha steps, and — through the bead positions — the composition of
// this app's own placement math over a four-to-eight-level Torus chain.
//
// It is also what makes a SEED mean something across the two apps, the same way
// the Hyperglyph Generator's harness does: `randomDesign` runs on this repo's
// CPython Mersenne Twister port, and the ORDER of its draws is the
// specification.

import { describe, expect, it } from 'vitest'
import {
  buildChannels,
  buildEpicycleNodes,
  closureFrames,
  describeDesign,
  frameCount,
  harmonicsOf,
  preset,
  randomDesign,
  slug,
  trailSampling,
} from './epicycles'
import type { EpicycleDesign } from './epicycles'
import { designToJson } from './epicycles'
import { PythonRandom } from './pythonRandom'
import { traceEpicyclePath } from '../render/epicyclePath'
import type { GvNode } from './types'
import fixtureRaw from './fixtures/epicycles.json?raw'

interface FixtureNode {
  id: number
  type: number
  parent_id: number
  branch_level: number
  translate_x: number
  translate_y: number
  translate_z: number
  rotate_x: number
  rotate_y: number
  rotate_z: number
  scale_x: number
  scale_y: number
  scale_z: number
  color_r: number
  color_g: number
  color_b: number
  color_a: number
  geometry: number
  hide: number
  topo: number
  ratio: number
  rotation_mode: number
  translate_rate_x: number
  translate_rate_y: number
  text: string
  child_id: number
  ch_input_id: number
}

interface Fixture {
  harmonics: Array<{ rates: number[]; harmonics: number[] }>
  closure: Array<{ rates: number[][]; closes: number | null; frames: number }>
  scenes: Array<{
    preset: string
    design: Record<string, unknown>
    self_drawing: boolean
    start_id: number
    parent_id: number
    base_branch_level: number
    include_world: boolean
    frames: number
    trail_step: number
    trail_beads: number
    describe: {
      arms: number
      frames: number
      closes: number | null
      harmonics: number[]
      spectrum: Array<[number, number]>
      half_span: number
      z_extent: number
      planar: boolean
    }
    nodes: FixtureNode[]
  }>
  channels: Array<{
    preset: string
    trail_points: number
    frames: number
    map: Array<[number, number, string]>
    sample_frames: number[]
    tracks: Record<string, number[]>
  }>
  random: Array<{
    seed: number
    n_arms: number | null
    allow_3d: boolean
    design: Record<string, unknown>
  }>
  slugs: Record<string, string>
}

const fixture = JSON.parse(fixtureRaw) as Fixture

/** Rebuild the design the dump recorded, so nothing depends on preset drift. */
function designOf(dict: Record<string, unknown>): EpicycleDesign {
  const arms = dict.arms as Array<Record<string, number>>
  return {
    name: String(dict.name),
    arms: arms.map((a) => ({
      length: a.length,
      rateX: a.rate_x,
      phaseX: a.phase_x,
      rateY: a.rate_y,
      phaseY: a.phase_y,
      tube: a.tube,
      tilt: a.tilt,
    })),
    penSize: Number(dict.pen_size),
    ringRatio: Number(dict.ring_ratio),
    showRings: Boolean(dict.show_rings),
    showArms: Boolean(dict.show_arms),
    armRatio: Number(dict.arm_ratio),
    trail: Boolean(dict.trail),
    trailPoints: Number(dict.trail_points),
    selfDrawing: Boolean(dict.self_drawing),
    beadGroup: Number(dict.bead_group),
    frames: (dict.frames as number | null) ?? null,
  }
}

/** The desktop's own bead tolerance: the node CSV's 6-decimal write precision,
 *  amplified by the parent scales the offsets pass through. */
const BEAD_TOLERANCE = 1e-6
const FLOAT_TOLERANCE = 1e-9

function intFields(node: GvNode, row: FixtureNode): void {
  expect(node.id).toBe(row.id)
  expect(node.type).toBe(row.type)
  expect(node.parentId).toBe(row.parent_id)
  expect(node.branchLevel).toBe(row.branch_level)
  expect(node.color.r).toBe(row.color_r)
  expect(node.color.g).toBe(row.color_g)
  expect(node.color.b).toBe(row.color_b)
  expect(node.color.a).toBe(row.color_a)
  expect(node.geometry).toBe(row.geometry)
  expect(node.hide).toBe(row.hide)
  expect(node.topo).toBe(row.topo)
  expect(node.rotationMode).toBe(row.rotation_mode)
  expect(Number(node.extras.child_id ?? 0)).toBe(row.child_id)
  expect(Number(node.extras.ch_input_id ?? 0)).toBe(row.ch_input_id)
  expect(node.text).toBe(row.text)
}

describe('epicycle parity: the harmonic ladder', () => {
  for (const c of fixture.harmonics) {
    it(`h(${c.rates.join(', ')}) = ${c.harmonics.join(', ')}`, () => {
      const got = harmonicsOf(c.rates)
      expect(got).toHaveLength(c.harmonics.length)
      got.forEach((v, i) => expect(v).toBeCloseTo(c.harmonics[i], 12))
    })
  }
})

describe('epicycle parity: closure in exact rationals', () => {
  for (const c of fixture.closure) {
    it(`rates ${JSON.stringify(c.rates)} close at ${c.closes}`, () => {
      const design = preset('Cardioid (2 terms)')
      design.arms = c.rates.map(([rx, ry]) => ({
        length: 10,
        rateX: rx,
        phaseX: 0,
        rateY: ry,
        phaseY: 0,
        tube: 0,
        tilt: 0,
      }))
      expect(closureFrames(design)).toBe(c.closes)
      expect(frameCount(design)).toBe(c.frames)
    })
  }
})

describe('epicycle parity: whole scenes, field for field', () => {
  for (const scene of fixture.scenes) {
    const label =
      `${scene.preset}${scene.self_drawing ? ' (self-drawing)' : ''} ` +
      `— ${scene.nodes.length} node(s)`
    it(label, () => {
      const design = designOf(scene.design)
      expect(frameCount(design)).toBe(scene.frames)
      const [step, beads] = trailSampling(design, scene.frames)
      expect(step).toBe(scene.trail_step)
      expect(beads).toBe(scene.trail_beads)

      const path = traceEpicyclePath(design, scene.frames)
      const nodes = buildEpicycleNodes(design, {
        startId: scene.start_id,
        parentId: scene.parent_id,
        baseBranchLevel: scene.base_branch_level,
        includeWorld: scene.include_world,
        path,
      })

      expect(nodes).toHaveLength(scene.nodes.length)
      nodes.forEach((node, i) => {
        const row = scene.nodes[i]
        intFields(node, row)
        // A bead's translate IS a sampled point of the traced curve, so it
        // takes the path tolerance; everything else is authored arithmetic.
        const tol = row.topo === 0 && row.geometry === 22 ? BEAD_TOLERANCE : FLOAT_TOLERANCE
        expect(node.translate.x).toBeCloseTo(row.translate_x, -Math.log10(tol))
        expect(node.translate.y).toBeCloseTo(row.translate_y, -Math.log10(tol))
        expect(node.translate.z).toBeCloseTo(row.translate_z, -Math.log10(tol))
        expect(node.rotate.x).toBeCloseTo(row.rotate_x, 9)
        expect(node.rotate.y).toBeCloseTo(row.rotate_y, 9)
        expect(node.rotate.z).toBeCloseTo(row.rotate_z, 9)
        expect(node.scale.x).toBeCloseTo(row.scale_x, 9)
        expect(node.scale.y).toBeCloseTo(row.scale_y, 9)
        expect(node.scale.z).toBeCloseTo(row.scale_z, 9)
        expect(node.ratio).toBeCloseTo(row.ratio, 9)
        expect(node.translateRate.x).toBeCloseTo(row.translate_rate_x, 9)
        expect(node.translateRate.y).toBeCloseTo(row.translate_rate_y, 9)
      })
    })
  }
})

describe('epicycle parity: the measured readout', () => {
  for (const scene of fixture.scenes) {
    it(`${scene.preset} reports the desktop's own figures`, () => {
      const design = designOf(scene.design)
      const path = traceEpicyclePath(design, scene.frames)
      const report = describeDesign(design, path, scene.frames)
      const want = scene.describe

      expect(report.arms).toBe(want.arms)
      expect(report.frames).toBe(want.frames)
      expect(report.closes).toBe(want.closes)
      expect(report.planar).toBe(want.planar)
      report.harmonics.forEach((h, i) => expect(h).toBeCloseTo(want.harmonics[i], 12))
      expect(report.halfSpan).toBeCloseTo(want.half_span, 6)
      expect(report.zExtent).toBeCloseTo(want.z_extent, 6)

      // The AMPLITUDES are compared in order — that is the spectrum itself, and
      // any real disagreement between the two transforms shows up here.
      expect(report.spectrum).toHaveLength(want.spectrum.length)
      const wantAmps = want.spectrum.map(([, a]) => a)
      report.spectrum.forEach(([, a], i) => expect(a).toBeCloseTo(wantAmps[i], 6))

      // The HARMONICS are compared as a set, and only where the amplitude says
      // which bin is meant. At the list's cut-off two symmetric sidebands can
      // tie to within an ulp (Deep chain: ±3 and 7 at 0.2535709570444…), and
      // which of them numpy's argsort — quicksort, not stable — happened to
      // keep is a fact about neither engine. Every entry above that tie must
      // still match exactly.
      const cut = wantAmps[wantAmps.length - 1]
      const unambiguous = (a: number) => Math.abs(a - cut) > 1e-9 * Math.max(1, Math.abs(cut))
      const mine = new Set(report.spectrum.map(([h]) => Number(h.toFixed(9))))
      for (const [h, a] of want.spectrum) {
        if (!unambiguous(a)) continue
        expect(mine.has(Number(h.toFixed(9))), `harmonic ${h} missing`).toBe(true)
      }
    })
  }
})

describe('epicycle parity: the self-drawing channel tracks', () => {
  for (const c of fixture.channels) {
    it(`${c.preset} at ${c.trail_points} points`, () => {
      const design = preset(c.preset)
      design.selfDrawing = true
      design.trailPoints = c.trail_points
      expect(frameCount(design)).toBe(c.frames)

      const channels = buildChannels(design, c.frames)
      expect(channels.map).toHaveLength(c.map.length)
      channels.map.forEach((row, i) => {
        expect([row.channelId, row.trackId, row.attribute]).toEqual(c.map[i])
      })
      for (const [id, samples] of Object.entries(c.tracks)) {
        const column = channels.tracks.get(Number(id))
        expect(column, `track ${id} missing`).toBeDefined()
        c.sample_frames.forEach((f, i) => {
          expect(column![f]).toBeCloseTo(samples[i], 9)
        })
      }
    })
  }
})

describe('epicycle parity: a seed names the same design', () => {
  for (const c of fixture.random) {
    it(`seed ${c.seed}, ${c.n_arms ?? 'auto'} arms, 3-D ${c.allow_3d}`, () => {
      const design = randomDesign(
        new PythonRandom(c.seed),
        c.n_arms,
        c.allow_3d,
        `Epitrochoid_${c.seed}`,
      )
      expect(designToJson(design)).toEqual(c.design)
    })
  }
})

describe('epicycle parity: filename stems', () => {
  for (const [name, want] of Object.entries(fixture.slugs)) {
    it(`"${name}" → ${want}`, () => {
      expect(slug(name)).toBe(want)
    })
  }
})
